import{_ as a,o as s,c as i,al as t}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Hawkeye Visualizer","description":"","frontmatter":{},"headers":[],"relativePath":"ko/sim_hawkeye/index.md","filePath":"ko/sim_hawkeye/index.md"}'),n={name:"ko/sim_hawkeye/index.md"};function l(r,e,h,o,p,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="hawkeye-visualizer" tabindex="-1">Hawkeye Visualizer <a class="header-anchor" href="#hawkeye-visualizer" aria-label="Permalink to &quot;Hawkeye Visualizer&quot;">​</a></h1><p><a href="https://px4.github.io/Hawkeye/" target="_blank" rel="noreferrer">Hawkeye</a> is a real-time 3D flight <em>visualizer</em> for PX4.</p><p>Hawkeye is the natural pair for <a href="./../sim_sih/">SIH</a> — SIH runs the physics of an aircraft simulation and outputs MAVLink <a href="https://mavlink.io/en/messages/common.html#HIL_STATE_QUATERNION" target="_blank" rel="noreferrer">HIL_STATE_QUATERNION</a> messages, Hawkeye uses these to show you what&#39;s happening.</p><p>Hawkeye has zero runtime dependencies, supports up to 16 vehicles simultaneously, and can replay PX4 ULog (<code>.ulg</code>) flight logs with transport controls, markers, and multi-drone correlation analysis.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><h3 id="macos-homebrew" tabindex="-1">macOS (Homebrew) <a class="header-anchor" href="#macos-homebrew" aria-label="Permalink to &quot;macOS (Homebrew)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PX4/px4</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PX4/px4/hawkeye</span></span></code></pre></div><h3 id="linux-debian-ubuntu" tabindex="-1">Linux (Debian/Ubuntu) <a class="header-anchor" href="#linux-debian-ubuntu" aria-label="Permalink to &quot;Linux (Debian/Ubuntu)&quot;">​</a></h3><p>Download the <code>.deb</code> from the <a href="https://github.com/PX4/Hawkeye/releases/latest" target="_blank" rel="noreferrer">Hawkeye releases page</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hawkeye-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.deb</span></span></code></pre></div><h3 id="windows-and-source-builds" tabindex="-1">Windows and source builds <a class="header-anchor" href="#windows-and-source-builds" aria-label="Permalink to &quot;Windows and source builds&quot;">​</a></h3><p>For Ubuntu 24.04 or later in WSL2 you can install the packages in the same way:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hawkeye-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.deb</span></span></code></pre></div><p>For other versions of Ubuntu (or native Windows builds) you may need to <a href="https://px4.github.io/Hawkeye/developer/build" target="_blank" rel="noreferrer">Build from source</a> (Hawkeye docs).</p><h2 id="usage-with-sih" tabindex="-1">Usage with SIH <a class="header-anchor" href="#usage-with-sih" aria-label="Permalink to &quot;Usage with SIH&quot;">​</a></h2><p>Start PX4 SIH, then launch Hawkeye in a separate terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hawkeye</span></span></code></pre></div><p>Hawkeye listens on UDP port 19410 — the same port SIH sends <a href="https://mavlink.io/en/messages/common.html#HIL_STATE_QUATERNION" target="_blank" rel="noreferrer">HIL_STATE_QUATERNION</a> on — so no configuration is needed. The vehicle appears in the Hawkeye window as soon as SIH starts streaming.</p><p>For fixed-wing or tailsitter simulation, Hawkeye auto-detects the vehicle type from MAVLink <code>HEARTBEAT</code> and loads the matching 3D model.</p><h2 id="full-documentation" tabindex="-1">Full documentation <a class="header-anchor" href="#full-documentation" aria-label="Permalink to &quot;Full documentation&quot;">​</a></h2><p>Complete documentation — including multi-vehicle SITL, ULog replay, HUD modes, camera controls, and correlation analysis — lives at <strong><a href="https://px4.github.io/Hawkeye/" target="_blank" rel="noreferrer">px4.github.io/Hawkeye</a></strong>.</p><ul><li><a href="https://px4.github.io/Hawkeye/first-sitl" target="_blank" rel="noreferrer">First SITL run</a> — the shortest path from install to seeing a vehicle move</li><li><a href="https://px4.github.io/Hawkeye/multi_drone" target="_blank" rel="noreferrer">Multi-Drone Replay</a> — compare multiple flights with deconfliction and correlation</li><li><a href="https://px4.github.io/Hawkeye/sitl" target="_blank" rel="noreferrer">Live SITL Integration</a> — single-vehicle and multi-instance swarm workflows</li><li><a href="https://px4.github.io/Hawkeye/cli" target="_blank" rel="noreferrer">Command-Line Reference</a> — every CLI flag with examples</li><li><a href="https://github.com/PX4/Hawkeye" target="_blank" rel="noreferrer">Source code</a></li></ul>`,22)])])}const c=a(n,[["render",l]]);export{u as __pageData,c as default};
